{"kind": "content", "icon": "🏃", "head": "नक़ली आलसी भागे", "points": ["आग बढ़ती देख सारे धूर्त (नक़ली आलसी) उठकर भाग खड़े हुए", "फिर थोड़े-बहुत आलसी (ईषदलसाः) भी भाग गए", "यानी जिनमें ज़रा-सा भी दम था, वे सब जान बचाकर भागे", "पर चार पुरुष वहीं सोए रहे — और आपस में बातें करने लगे!", "यही चार थे — असली, पक्के आलसी"], "say": "आग को बढ़ता देखकर, सारे धूर्त, यानी नक़ली आलसी, झट से उठकर, भाग खड़े हुए। उनका सारा नाटक, एक पल में ख़त्म हो गया। उनके बाद, जो थोड़े-बहुत आलसी थे, वे भी भाग गए। यानी जिनमें, ज़रा-सा भी दम था, वे सब, अपनी जान बचाकर भागे। पर चार पुरुष, वहीं सोए रहे। और केवल सोए ही नहीं रहे, बल्कि लेटे-लेटे, आपस में बातें करने लगे! यही चार थे, असली, पक्के आलसी। अब सुनिए, इन चारों ने क्या-क्या कहा। यह कथा का, सबसे मज़ेदार हिस्सा है।"},
{"kind": "eq", "icon": "1️⃣", "head": "पहला आलसी", "words": "कपड़े से मुँह ढके-ढके ही बोला —", "eq": "अहो! कथमयं कोलाहलः?", "note": "अर्थ: अरे! यह शोर कैसा है? · कोलाहलः = शोर-गुल", "say": "पहला आलसी। उसने तो, मुँह पर से कपड़ा भी नहीं हटाया। कपड़े से मुँह ढके-ढके ही बोला, अहो! कथमयं कोलाहलः? शब्द समझिए। अहो, अरे। कथम्, कैसा। अयम्, यह। कोलाहलः, शोर-गुल। अर्थ है, अरे! यह शोर कैसा है? यानी बाहर लोग, आग-आग चिल्ला रहे हैं, भाग रहे हैं, और यह महाशय, आँख खोलकर देखने की भी, तकलीफ़ नहीं करना चाहते। बस पूछ रहे हैं, यह शोर क्यों हो रहा है?"},
{"kind": "eq", "icon": "2️⃣", "head": "दूसरा आलसी", "words": "उसने अंदाज़ा लगाया —", "eq": "तर्क्यते यदस्मिन् गृहे अग्निर्लग्नोऽस्ति।", "note": "अर्थ: लगता है कि इस घर में आग लग गई है · तर्क्यते = अनुमान होता है", "say": "दूसरा आलसी। उसने लेटे-लेटे ही, अंदाज़ा लगाया, और बोला, तर्क्यते, यदस्मिन् गृहे, अग्निर्लग्नोऽस्ति। शब्द समझिए। तर्क्यते, यानी अनुमान होता है, लगता है। यत्, कि। अस्मिन् गृहे, इस घर में। अग्निः, आग। लग्नः अस्ति, लगी हुई है। अर्थ है, लगता है, कि इस घर में, आग लग गई है। यानी इन्हें पता चल गया है, कि आग लगी है। पर क्या वे उठे? नहीं! बस आराम से बता रहे हैं, जैसे किसी और के घर की ख़बर सुना रहे हों।"},
{"kind": "eq", "icon": "3️⃣", "head": "तीसरा आलसी", "words": "उसे उम्मीद थी कि कोई दूसरा आकर बचा लेगा —", "eq": "कोऽपि तथा धार्मिको नास्ति य इदानीं जलार्द्रैर्वासोभिः कटैर्वा अस्मान् प्रावृणोति?", "note": "अर्थ: क्या कोई ऐसा धर्मात्मा नहीं है, जो अभी गीले कपड़ों या चटाइयों से हमें ढँक दे?", "say": "तीसरा आलसी। यह सबसे अनोखा है। वह बोला, कोऽपि तथा धार्मिको नास्ति, य इदानीं, जलार्द्रैर्वासोभिः, कटैर्वा, अस्मान् प्रावृणोति? शब्द समझिए। कः अपि, कोई भी। धार्मिकः, धर्मात्मा, भला आदमी। न अस्ति, नहीं है। इदानीम्, अभी। जलार्द्रैः वासोभिः, पानी से गीले कपड़ों से। कटैः वा, या चटाइयों से। अस्मान्, हमें। प्रावृणोति, ढँक दे। अर्थ है, क्या यहाँ कोई ऐसा धर्मात्मा नहीं है, जो अभी, पानी से गीले कपड़ों, या चटाइयों से, हमें ढँक दे? सोचिए! आग लगी है, और यह आदमी, उठकर भागने की जगह, यह चाह रहा है, कि कोई और आकर, उसके ऊपर गीला कपड़ा डाल दे!"},
{"kind": "eq", "icon": "4️⃣", "head": "चौथा आलसी — सबसे बड़ा!", "words": "उसे तो बोलना भी मेहनत लग रहा था —", "eq": "अये वाचालाः! कति वचनानि वक्तुं शक्नुथ? तूष्णीं कथं न तिष्ठथ?", "note": "अर्थ: अरे बातूनियो! कितनी बातें बोल सकते हो? चुप क्यों नहीं रहते? · वाचालः = बातूनी · तूष्णीम् = चुप", "say": "और अब चौथा आलसी, जो इन सबमें, सबसे बड़ा आलसी निकला। उसे तो, इन तीनों का बोलना भी, पसंद नहीं आया। वह झुँझलाकर बोला, अये वाचालाः! कति वचनानि, वक्तुं शक्नुथ? तूष्णीं, कथं न तिष्ठथ? शब्द समझिए। अये, अरे। वाचालाः, बातूनियो। कति वचनानि, कितनी बातें। वक्तुं शक्नुथ, बोल सकते हो। तूष्णीम्, चुप। कथं न तिष्ठथ, क्यों नहीं रहते। अर्थ है, अरे बातूनियो! तुम लोग, कितनी बातें बोल सकते हो? चुप क्यों नहीं रहते? यानी इसके लिए तो, बोलना भी मेहनत का काम है! आग से ज़्यादा, इसे इस बात की तकलीफ़ है, कि इसकी नींद ख़राब हो रही है।"},
{"kind": "table", "icon": "📋", "head": "चारों आलसियों के कथन", "eq": "यह तालिका परीक्षा के लिए बहुत ज़रूरी है", "rows": [["आलसी", "क्या कहा", "आलस का स्तर"], ["पहला", "यह शोर कैसा है? (मुँह ढके-ढके)", "आँख खोलना भी भारी"], ["दूसरा", "लगता है घर में आग लगी है", "जानकर भी नहीं उठा"], ["तीसरा", "कोई गीले कपड़े/चटाई से हमें ढँक दे", "दूसरों के भरोसे"], ["चौथा", "अरे बातूनियो, चुप क्यों नहीं रहते?", "बोलना भी मेहनत"]], "say": "चारों आलसियों के कथन, एक तालिका में देखिए। यह परीक्षा के लिए, बहुत ज़रूरी है। पहले ने, मुँह ढके-ढके पूछा, यह शोर कैसा है? उसके लिए, आँख खोलना भी भारी था। दूसरे ने कहा, लगता है, घर में आग लगी है। वह जानकर भी, नहीं उठा। तीसरे ने कहा, कोई धर्मात्मा, गीले कपड़े या चटाई से, हमें ढँक दे। वह दूसरों के भरोसे था। और चौथे ने कहा, अरे बातूनियो, चुप क्यों नहीं रहते? उसके लिए तो, बोलना भी मेहनत था। परीक्षा में पूछा जाता है, कि किस आलसी ने क्या कहा।"},
{"kind": "content", "icon": "🧑‍🚒", "head": "बाल पकड़कर बचाया", "points": ["चारों की बातें सुनकर अधिकारियों को पक्का विश्वास हो गया: ये ही असली आलसी हैं", "तब तक आग की लपटें उन चारों के ऊपर गिरने ही वाली थीं", "अधिकारी दौड़े, और उन्हें मरने के डर से बाल पकड़कर घसीटते हुए बाहर निकाला", "संस्कृत: 'केशेषु आकृष्य गृहात् बहिः कृताः'", "केशेषु = बालों में · आकृष्य = खींचकर · बहिः = बाहर"], "say": "इन चारों की बातें सुनकर, अधिकारियों को पक्का विश्वास हो गया, कि यही चार, असली आलसी हैं। पर तब तक, आग की लपटें, उन चारों के ऊपर, गिरने ही वाली थीं। अधिकारी दौड़े। उन्हें डर था, कि ये बेचारे, जलकर मर न जाएँ। उन्होंने, चारों को, बाल पकड़कर, घसीटते हुए, घर से बाहर निकाला। संस्कृत में, केशेषु आकृष्य, गृहात् बहिः कृताः। केशेषु, यानी बालों में। आकृष्य, खींचकर। बहिः, बाहर। सोचिए, ये चारों इतने आलसी थे, कि अपनी जान बचाने के लिए भी, ख़ुद नहीं उठे। दूसरों को, उन्हें घसीटकर निकालना पड़ा।"},
{"kind": "eq", "icon": "📜", "head": "कथा का श्लोक", "words": "पतिरेव गतिः स्त्रीणां बालानां जननी गतिः।", "eq": "नालसानां गतिः काचिल्लोके कारुणिकं विना॥", "note": "गतिः = सहारा, शरण · कारुणिकं विना = दयालु के बिना", "say": "तब उन अधिकारियों ने, उन चारों को देखकर, एक श्लोक पढ़ा। यह पाठ का, एकमात्र श्लोक है, और बहुत ज़रूरी है। ध्यान से सुनिए। पतिरेव गतिः स्त्रीणां, बालानां जननी गतिः। नालसानां गतिः काचित्, लोके कारुणिकं विना। एक बार फिर। पतिः एव, गतिः स्त्रीणाम्। बालानां, जननी गतिः। न अलसानां, गतिः काचित्। लोके, कारुणिकं विना।"},
{"kind": "table", "icon": "📋", "head": "श्लोक — शब्दार्थ और अर्थ", "eq": "आलसियों का सहारा कौन?", "rows": [["संस्कृत", "हिंदी अर्थ"], ["पतिः एव", "पति ही"], ["गतिः", "सहारा, शरण"], ["स्त्रीणाम्", "स्त्रियों का"], ["बालानाम्", "बच्चों का"], ["जननी", "माँ"], ["अलसानाम्", "आलसियों का"], ["न काचित्", "कोई नहीं"], ["लोके", "संसार में"], ["कारुणिकं विना", "दयालु व्यक्ति के बिना"]], "say": "श्लोक के शब्दार्थ। पतिः एव, पति ही। गतिः, सहारा, शरण। स्त्रीणाम्, स्त्रियों का। बालानाम्, बच्चों का। जननी, माँ। अलसानाम्, आलसियों का। न काचित्, कोई नहीं। लोके, संसार में। कारुणिकं विना, दयालु व्यक्ति के बिना। अब पूरा अर्थ। उस समय की मान्यता के अनुसार, स्त्रियों का सहारा, पति है। बच्चों का सहारा, माँ है। पर आलसियों का, इस संसार में, दयालु व्यक्ति के बिना, कोई सहारा नहीं है। यानी आलसी, ख़ुद तो कुछ करता नहीं। अगर कोई दयालु, उस पर दया न करे, तो वह बच ही नहीं सकता।"},
{"kind": "content", "icon": "🎁", "head": "कथा का अंत", "points": ["परीक्षा पूरी हुई — चार असली आलसी पहचान लिए गए", "नक़ली आलसी (धूर्त) भगा दिए गए", "मंत्री वीरेश्वर ने उन चारों आलसियों को पहले से भी ज़्यादा अन्न-वस्त्र दिलवाए", "संस्कृत: 'तेभ्यः पूर्वस्मादधिकतरं वस्तु मन्त्री प्रादात्'", "यानी: मंत्री की दया असली ज़रूरतमंद तक पहुँची"], "say": "कथा का अंत। परीक्षा पूरी हुई। चार असली आलसी, पहचान लिए गए, और नक़ली आलसी, यानी धूर्त, भगा दिए गए। इसके बाद, मंत्री वीरेश्वर ने, उन चारों आलसियों को, पहले से भी ज़्यादा, अन्न और वस्त्र दिलवाए। संस्कृत में, तेभ्यः, पूर्वस्मात् अधिकतरं वस्तु, मन्त्री प्रादात्। यानी मंत्री ने, उन्हें पहले से अधिक वस्तुएँ दीं। इस तरह, मंत्री की दया, सही लोगों तक पहुँची, और ठग लोग, बाहर हो गए।"},
{"kind": "question", "icon": "🤔", "head": "सोचिए", "q": "क्या यह कथा आलसी बनने की तारीफ़ करती है?", "a": "नहीं — यह आलस पर हँसती है (व्यंग्य)। आलसी इतना लाचार हो जाता है कि जान बचाने के लिए भी दूसरों पर निर्भर रहता है", "pause": 7, "say": "सोचिए। कथा में, आलसियों को इनाम मिला। तो क्या यह कथा, आलसी बनने की तारीफ़ करती है? ... बिल्कुल नहीं। यह कथा, आलस पर हँसती है, यह एक व्यंग्य है। विद्यापति दिखाना चाहते हैं, कि आलसी आदमी, इतना लाचार हो जाता है, कि अपनी जान बचाने के लिए भी, दूसरों पर निर्भर रहता है। उसे, बाल पकड़कर घसीटना पड़ता है। क्या आप, ऐसा जीवन चाहेंगे? जिसमें अपना हर काम, दूसरों की दया पर टिका हो? इसीलिए तो कहा गया, आलस्य, शरीर में बैठा, सबसे बड़ा शत्रु है।"},
{"kind": "content", "icon": "🎯", "head": "कथा से सीख", "points": ["आलस्य मनुष्य का सबसे बड़ा शत्रु है — उसे अपने पास न आने दें", "आलसी व्यक्ति हमेशा दूसरों की दया पर जीता है — उसका कोई सम्मान नहीं", "दान हमेशा सही, ज़रूरतमंद व्यक्ति को ही देना चाहिए — जाँच-परखकर", "धूर्तता (ठगी) का भेद एक दिन खुल ही जाता है", "दयालु होना अच्छा है — पर समझदारी के साथ"], "say": "इस कथा से, हमें क्या सीख मिलती है? पहली, आलस्य, मनुष्य का सबसे बड़ा शत्रु है, उसे अपने पास न आने दें। दूसरी, आलसी व्यक्ति, हमेशा दूसरों की दया पर जीता है, और समाज में, उसका कोई सम्मान नहीं होता। तीसरी, दान हमेशा, सही और ज़रूरतमंद व्यक्ति को ही देना चाहिए, जाँच-परखकर। चौथी, धूर्तता का, यानी ठगी का भेद, एक दिन खुल ही जाता है, जैसे आग लगते ही, नक़ली आलसी भाग खड़े हुए। और पाँचवीं, मंत्री वीरेश्वर की तरह, दयालु होना अच्छा है, पर दया के साथ, समझदारी भी ज़रूरी है।"},
{"kind": "table", "icon": "📋", "head": "शब्दार्थ", "eq": "पाठ के ज़रूरी शब्द", "rows": [["संस्कृत शब्द", "हिंदी अर्थ"], ["अलसः", "आलसी"], ["रिपुः", "शत्रु"], ["कारुणिकः", "दयालु"], ["दुर्गतः", "ग़रीब, बुरी हालत वाला"], ["धूर्तः", "चालाक, ठग"], ["वह्निः", "आग"], ["कोलाहलः", "शोर-गुल"], ["वाचालः", "बातूनी"], ["तूष्णीम्", "चुप"], ["केशः", "बाल"], ["जननी", "माँ"], ["गतिः", "सहारा, शरण"]], "say": "पाठ के ज़रूरी शब्दार्थ। अलसः, आलसी। रिपुः, शत्रु। कारुणिकः, दयालु। दुर्गतः, ग़रीब, बुरी हालत वाला। धूर्तः, चालाक, ठग। वह्निः, आग। कोलाहलः, शोर-गुल। वाचालः, बातूनी। तूष्णीम्, चुप। केशः, बाल। जननी, माँ। और गतिः, सहारा, शरण।"},
{"kind": "table", "icon": "📋", "head": "व्याकरण", "eq": "संधि, समास, प्रत्यय", "rows": [["शब्द", "जानकारी"], ["कोऽपि", "कः + अपि"], ["नास्ति", "न + अस्ति (दीर्घ संधि)"], ["लग्नोऽस्ति", "लग्नः + अस्ति"], ["नालसानाम्", "न + अलसानाम्"], ["पतिरेव", "पतिः + एव"], ["कथमयम्", "कथम् + अयम्"], ["अलसकथा", "अलसानां कथा (षष्ठी तत्पुरुष)"], ["अलसशाला", "अलसानां शाला (षष्ठी तत्पुरुष)"], ["आकृष्य", "आ + कृष् + ल्यप्"], ["वक्तुम्", "वच् + तुमुन्"]], "say": "अब व्याकरण। पहले संधि-विच्छेद। कोऽपि, यानी कः, और अपि। नास्ति, यानी न, और अस्ति, यह दीर्घ संधि है। लग्नोऽस्ति, यानी लग्नः, और अस्ति। नालसानाम्, यानी न, और अलसानाम्। पतिरेव, यानी पतिः, और एव। कथमयम्, यानी कथम्, और अयम्। अब समास। अलसकथा, इसका विग्रह है, अलसानां कथा। अलसशाला, यानी अलसानां शाला। दोनों, षष्ठी तत्पुरुष समास हैं। अब प्रत्यय। आकृष्य, आ उपसर्ग, कृष् धातु, और ल्यप् प्रत्यय से बना है। और वक्तुम्, वच् धातु, और तुमुन् प्रत्यय से बना है, अर्थ है, बोलने के लिए।"},
{"kind": "content", "icon": "🌾", "head": "बिहार का गौरव: विद्यापति", "points": ["विद्यापति का जन्म-स्थान बिसफी (मधुबनी) — आज भी वहाँ स्मारक", "उनके मैथिली गीत 600 साल बाद भी मिथिला के हर शादी-ब्याह, पूजा में गाए जाते हैं", "दरभंगा में हर साल 'विद्यापति पर्व समारोह'", "कथा भी मिथिला की, लेखक भी मिथिला के — यह पाठ हमारा अपना है", "मिथिला: राजा जनक, सीता, याज्ञवल्क्य, मंडन मिश्र की विद्या-भूमि"], "say": "यह पाठ, हम बिहार के बच्चों के लिए, बहुत ख़ास है। इसके लेखक विद्यापति का जन्म-स्थान, मधुबनी ज़िले का बिसफी गाँव है, जहाँ आज भी उनका स्मारक है। उनके मैथिली गीत, छह सौ साल बाद भी, मिथिला के हर शादी-ब्याह और पूजा में, गाए जाते हैं। दरभंगा में, हर साल, विद्यापति पर्व समारोह मनाया जाता है। और देखिए, इस पाठ की कथा भी, मिथिला की है, और लेखक भी, मिथिला के हैं। यानी यह पाठ, पूरी तरह हमारा अपना है। मिथिला, प्राचीन काल से ही, विद्या की भूमि रही है। राजा जनक, सीता, ऋषि याज्ञवल्क्य, और विद्वान मंडन मिश्र, सब इसी धरती से जुड़े हैं।"},
{"kind": "list", "icon": "📝", "head": "सार", "points": ["लेखक: विद्यापति (मैथिल कोकिल) · ग्रंथ: पुरुषपरीक्षा", "मिथिला का मंत्री वीरेश्वर — दानी, दयालु; आलसियों को भी अन्न-वस्त्र देता था", "धूर्त नक़ली आलसी बनकर आने लगे → अधिकारियों ने आलसशाला में आग लगाकर परीक्षा ली", "सब भागे, चार असली आलसी पड़े-पड़े बातें करते रहे → बाल पकड़कर बचाए गए", "सीख: आलस्य शरीर में रहने वाला सबसे बड़ा शत्रु है"], "say": "आज का सार। एक, लेखक विद्यापति हैं, जिन्हें मैथिल कोकिल कहते हैं, और यह कथा, उनके ग्रंथ पुरुषपरीक्षा से है। दो, मिथिला का मंत्री वीरेश्वर, दानी और दयालु था, और आलसियों को भी, अन्न और वस्त्र देता था। तीन, धूर्त लोग, नक़ली आलसी बनकर आने लगे, तो अधिकारियों ने, आलसशाला में आग लगाकर, परीक्षा ली। चार, सब भाग गए, पर चार असली आलसी, पड़े-पड़े बातें करते रहे, और उन्हें, बाल पकड़कर बचाया गया। पाँच, सीख यह है, कि आलस्य, शरीर में रहने वाला, सबसे बड़ा शत्रु है।"},
{"kind": "question", "icon": "❓", "head": "अभ्यास प्रश्न 1", "q": "'अलसकथा' के लेखक कौन हैं? यह किस ग्रंथ से ली गई है?", "a": "विद्यापति · 'पुरुषपरीक्षा'", "pause": 4, "say": "अब अभ्यास। वीडियो रोककर उत्तर सोचिए। पहला, अलसकथा के लेखक कौन हैं, और यह किस ग्रंथ से ली गई है? ... विद्यापति। पुरुषपरीक्षा से।"},
{"kind": "question", "icon": "❓", "head": "अभ्यास प्रश्न 2", "q": "मिथिला के मंत्री का क्या नाम था? वह कैसा था?", "a": "वीरेश्वर · दानशील और कारुणिक (दयालु)", "pause": 4, "say": "दूसरा, मिथिला के मंत्री का क्या नाम था, और वह कैसा था? ... वीरेश्वर। वह दानशील और कारुणिक, यानी दयालु था।"},
{"kind": "question", "icon": "❓", "head": "अभ्यास प्रश्न 3", "q": "अधिकारियों ने आलसियों की परीक्षा कैसे ली?", "a": "सोए हुए आलसियों की आलसशाला में आग लगवाकर", "pause": 4, "say": "तीसरा, अधिकारियों ने, आलसियों की परीक्षा कैसे ली? ... सोए हुए आलसियों की आलसशाला में, आग लगवाकर।"},
{"kind": "question", "icon": "❓", "head": "अभ्यास प्रश्न 4", "q": "आग लगने पर कितने आलसी नहीं भागे? उन्हें कैसे बचाया गया?", "a": "चार · बाल पकड़कर खींचकर बाहर निकाला गया", "pause": 5, "say": "चौथा, आग लगने पर, कितने आलसी नहीं भागे, और उन्हें कैसे बचाया गया? ... चार आलसी नहीं भागे। उन्हें, बाल पकड़कर, खींचकर बाहर निकाला गया।"},
{"kind": "question", "icon": "❓", "head": "अभ्यास प्रश्न 5", "q": "चौथे आलसी ने क्या कहा?", "a": "अरे बातूनियो! कितनी बातें बोल सकते हो? चुप क्यों नहीं रहते?", "pause": 5, "say": "पाँचवाँ, चौथे आलसी ने क्या कहा? ... अरे बातूनियो! कितनी बातें बोल सकते हो? चुप क्यों नहीं रहते?"},
